/* Extend existing Learn, Create and project surfaces. Private work never leaves this browser. */
(()=>{
 'use strict';
 const C=window.REISupportCore,D=window.REIStudies,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const link=(href,label,primary=false)=>`<a class="${primary?'path-button':'path-link'}" href="${esc(href)}" ${href.startsWith('https:')?'target="_blank" rel="noopener noreferrer"':''}>${esc(label)}</a>`;
 const roles={question:'Question / purpose',method:'Method / evidence',finding:'Finding / result',limitation:'Limitation / boundary'};
 const store=()=>window.REILearningStore.readSupport(),save=s=>{const ok=window.REILearningStore.writeSupport(s),status=document.querySelector('[data-library-persist]');if(status)status.textContent=ok?'Saved on this device and included in workspace backups.':'Not saved to browser storage. Keep this page open, retry, or download a workspace backup.';return ok;};
 const nav=active=>`<nav class="support-learning-nav" aria-label="Ways to learn">${[['lessons','#learn','Short lessons'],['papers','#library/papers','Read real papers'],['model','#library/model','See a whole project']].map(([id,href,title])=>`<a href="${href}" ${active===id?'aria-current="page"':''}>${title}</a>`).join('')}</nav>`;
 const saved=()=>'';
 function papers(){return window.REILibrary.shell(`<header class="library-heading"><h1>Read the study.<br><em>See the reasoning.</em></h1><p>Six real open-access studies, chosen to illustrate different research decisions. REI’s annotations are teaching interpretations; inspect the original methods and results yourself.</p></header>${nav('papers')}<label class="support-filter">Find a method or topic<input type="search" data-study-filter placeholder="Try interviews, sleep, experiment or engagement"></label><p data-study-count role="status">Six studies with original PDFs</p><ol class="support-studies">${D.studies.map(s=>`<li data-study-item data-study-search="${esc((s.title+' '+s.label+' '+s.skill).toLowerCase())}"><div><span class="path-muted">${esc(s.label)} · ${s.year}</span><h2>${link('#library/study/'+s.id,s.title)}</h2><p>${esc(s.skill)}</p><small>${esc(s.authors.join('; '))}</small></div><p>${esc(s.context)}</p></li>`).join('')}</ol><p data-study-empty hidden>No studies match. Try a broader topic or method.</p><details class="library-support"><summary>How this collection was prepared</summary><p>The authors’ CC BY PDFs are distributed unchanged, with their original attribution and notices. Short quotation anchors and PDF pages were checked against the originals. REI annotations, questions and the worked proposal are original teaching materials. This is a small teaching collection, not a complete literature search or certification of study quality.</p>${link('studies/ATTRIBUTION.json','Source and attribution record')}</details>${saved()}`);}
 function study(id){const s=D.studies.find(s=>s.id===id);if(!s)return papers();const r=store().papers[id]||{choice:null,reason:'',revealed:false},ordered=(s.challengeOrder||[0,1,2,3]).map(i=>s.annotations[i]);return window.REILibrary.shell(`<a class="path-back" href="#library/papers">← Real-paper collection</a><header class="library-heading"><h1>${esc(s.title)}</h1><p>${esc(s.authors.join('; '))} · ${s.year} · ${esc(s.venue)}</p><p>${esc(s.context)}</p><p>${esc(s.skill)}</p>${link(s.url,'Open the publisher’s full article')} ${link(s.pdf,'Open original PDF')}</header><section class="support-evidence-hunt"><h2>Find the evidence.</h2><p>Inspect the original paper, then choose the short passage anchor that most directly supports the statement. These snippets help you locate context; they are not a substitute for reading the full passage.</p><fieldset><legend>${esc(s.challenge)}</legend>${ordered.map((a,i)=>`<label class="library-choice"><input type="radio" name="study-choice" data-study-choice="${s.id}" value="${i}" ${r.choice===i?'checked':''}><span>“${esc(a.quote)}” <small>PDF page ${a.page}</small></span></label>`).join('')}</fieldset><p data-study-choice-feedback role="status">${r.choice===null?'Choose a passage to inspect its fit.':choiceFeedback(s,r.choice)}</p><label>Why does that passage support the statement?<textarea data-study-reason="${s.id}" maxlength="1500" rows="3">${esc(r.reason)}</textarea></label><button type="button" class="path-link" data-study-reveal="${s.id}">Compare with the teaching explanation</button><div data-study-model ${r.revealed?'':'hidden'}><p>${esc(s.annotations.find(a=>a.role==='finding').explanation)}</p><p>Your written explanation is not automatically graded. Check the result, context and boundary; revise your explanation if needed.</p></div><p data-study-writing-feedback role="status"></p></section><section class="support-annotations"><h2>Four decisions in this paper.</h2><p>Compare the original passage with REI’s interpretation. Boundary checks explicitly identify whether they are the authors’ stated limitation or REI’s own concern.</p>${s.annotations.map(a=>`<details><summary>${roles[a.role]}</summary><p class="path-muted">${esc(a.locator)}</p><blockquote>“${esc(a.quote)}”</blockquote><p>${esc(a.explanation)}</p>${link(s.pdf+'#page='+a.page,'Inspect this PDF page')}</details>`).join('')}</section><details class="support-source-copy"><summary>Keep this paper in a project</summary>${window.REILibrary.projectConnection()}<section class="support-save-source"><button type="button" class="path-button" data-study-save="${s.id}">Save source and PDF to project</button><p data-study-save-status role="status">Adds this source and its unmodified open-access PDF. Existing references and attached PDFs are preserved.</p></section></details>${saved()}`);}
 function choiceFeedback(s,i){const a=s.annotations[(s.challengeOrder||[0,1,2,3])[i]];return a.role==='finding'?'This anchor points to the reported finding. Read the surrounding results before deciding what it supports.':'This anchor concerns '+roles[a.role].toLowerCase()+'. It provides context, but inspect the reported finding for direct support of this particular statement.';}
 function model(){return window.REILibrary.shell(`<header class="library-heading"><h1>Follow one project.<br><em>See every connection.</em></h1><p>A complete teaching proposal with real published sources, linked evidence and a proposed interview design. The local study is illustrative: no local data has been collected and no local findings are claimed.</p></header>${nav('model')}<ol class="support-model-steps">${D.model.steps.map(([title,body],i)=>`<li><span aria-hidden="true">${i+1}</span><div><h2>${esc(title)}</h2><p>${esc(body)}</p></div></li>`).join('')}</ol><section class="support-model-use"><h2>Explore an editable practice copy.</h2><p>The copy opens in the existing project workspace with three real sources, source-linked annotations, a claim, methods and a proposed write-up. Its title and notes label it as a teaching example.</p><button type="button" class="path-button" data-model-copy>Save a practice copy</button><p data-model-status role="status">Uses one project slot. Existing projects are preserved.</p></section><details class="library-support"><summary>Read the complete proposed write-up</summary><pre class="support-proposal">${esc(D.model.proposal)}</pre></details>`);}
 const options=(headers,value,blank)=>`<option value="">${blank}</option>`+headers.map(h=>`<option ${value===h?'selected':''} value="${esc(h)}">${esc(h)}</option>`).join('');
 function analysis(){const v=store().analysis;let d;try{d=C.dataset(v.csv)}catch{}return window.REILibrary.shell(`<a class="path-back" href="#create">← Create</a><header class="library-heading"><h1>Explore your data.<br><em>Understand each number.</em></h1><p>Inspect a CSV, describe a numeric measure, compare group summaries or explore a linear association. Calculations stay on this device. This introductory tool does not select a valid design or run significance tests.</p></header>${window.REILibrary.projectConnection()}<div class="tool-workbench support-analysis"><section class="tool-input"><h2>Inspect before calculating</h2><form data-support-analysis><label>CSV file<input type="file" data-analysis-file accept=".csv,text/csv"></label><label>Or paste CSV with a header<textarea name="csv" maxlength="100000" rows="8" required>${esc(v.csv)}</textarea></label><p class="path-muted">Up to 2,000 rows, 30 columns and 100,000 characters. Use de-identified data. CSV text is included in backups when you save this analysis to a project.</p><button type="button" class="path-link" data-analysis-example>Try fictional practice data</button><button type="button" class="path-link" data-analysis-inspect>Inspect columns</button><p data-analysis-inspection role="status">${d?d.rows.length+' rows · '+d.headers.length+' columns. Verify their meanings before calculating.':'Load or paste a comma-separated CSV, then inspect its columns.'}</p><label>Source / dataset description<input name="source" maxlength="180" value="${esc(v.source)}" placeholder="Example: de-identified pilot survey, version 1"></label><label>Numeric column<select name="x" required>${options(d?.headers||[],v.x,'Choose the measure')}</select></label><label>Optional second numeric column<select name="y">${options(d?.headers||[],v.y,'No correlation')}</select></label><label>Optional group/category column<select name="group">${options(d?.headers||[],v.group,'No grouping')}</select></label><label>Measurement, selection and cleaning notes<textarea name="notes" rows="3" maxlength="2000">${esc(v.notes)}</textarea></label><button type="submit" class="path-button">Calculate and explain</button><p data-analysis-status role="status"></p></form></section><section class="support-analysis-result" data-analysis-output tabindex="-1" aria-label="Analysis results">${v.run?analysisResult(v):'<h2>Your analysis will appear here.</h2><p>Start with a clearly defined measure. Review missing and invalid cells, then inspect distributions and boundaries before interpreting a summary.</p>'}</section></div>${saved()}`,'create');}
 function scatter(a){if(!a.pairs.length)return '';const pairs=a.pairs.slice(0,500),xs=a.pairs.map(p=>p[0]),ys=a.pairs.map(p=>p[1]),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys),px=x=>55+(xmax===xmin?.5:(x-xmin)/(xmax-xmin))*510,py=y=>215-(ymax===ymin?.5:(y-ymin)/(ymax-ymin))*180;return `<figure class="support-scatter"><svg viewBox="0 0 600 260" role="img" aria-label="Scatterplot of ${esc(a.column)} and ${esc(a.second)}"><path d="M55 25V215H570" fill="none" stroke="currentColor"/>${pairs.map(([x,y])=>`<circle cx="${px(x).toFixed(2)}" cy="${py(y).toFixed(2)}" r="3" fill="currentColor" opacity=".7"/>`).join('')}<text x="55" y="242">${esc(C.fmt(xmin))}</text><text x="520" y="242">${esc(C.fmt(xmax))}</text><text x="4" y="35">${esc(C.fmt(ymax))}</text><text x="4" y="215">${esc(C.fmt(ymin))}</text></svg><figcaption>${esc(a.column)} (horizontal) and ${esc(a.second)} (vertical). ${pairs.length} of ${a.pairs.length} complete pairs displayed; the calculation uses all complete pairs.</figcaption></figure>`;}
 function analysisResult(v){try{const a=C.analyze(v),s=a.stats;return `<h2>Describe what you observed.</h2><p>${a.rows} original rows · ${s.n} valid numeric observations for ${esc(a.column)}. Displayed summaries are rounded to five significant figures.</p><div class="support-table-wrap" tabindex="0" aria-label="Scrollable data table"><table class="support-summary-table"><caption>Descriptive statistics for ${esc(a.column)}</caption><tbody>${[['Mean',s.mean],['Median',s.median],['Sample standard deviation',s.sd],['Minimum',s.min],['Maximum',s.max]].map(([label,n])=>`<tr><th scope="row">${label}</th><td>${C.fmt(n)}</td></tr>`).join('')}</tbody></table></div><details open><summary>What was excluded from this calculation?</summary><p>Missing values: ${a.excluded.missing.length}. Invalid numeric cells: ${a.excluded.invalid.length}. The original CSV is retained. Blank, NA, N/A, null and NaN count as missing; zero is a valid number.</p><p>Missing data rows: ${a.excluded.missing.join(', ')||'None'}. Invalid data rows: ${a.excluded.invalid.join(', ')||'None'}.</p><p>${a.duplicateRows} exact duplicate rows detected. They remain included; determine whether they are legitimate repeated records before removing anything.</p></details>${a.second?`<h3>Inspect the relationship</h3><p>Pearson r = ${C.fmt(a.correlation)} · ${a.pairs.length} complete pairs · ${a.pairExcluded} rows omitted from the paired calculation.</p>${scatter(a)}<p>A linear correlation can hide outliers or curved patterns. It is undefined here with fewer than three complete pairs or a constant column. It does not establish a causal effect or a population relationship.</p>`:''}${a.group?`<h3>Compare recorded groups</h3><div class="support-table-wrap" tabindex="0" aria-label="Scrollable data table"><table><caption>Summaries of valid ${esc(a.column)} values by ${esc(a.group)}</caption><thead><tr><th scope="col">Group</th><th scope="col">Numeric n</th><th scope="col">Mean</th><th scope="col">Median</th><th scope="col">Sample SD</th></tr></thead><tbody>${a.groups.slice(0,30).map(g=>`<tr><th scope="row">${esc(g.label)}</th><td>${g.n}</td><td>${C.fmt(g.mean)}</td><td>${C.fmt(g.median)}</td><td>${C.fmt(g.sd)}</td></tr>`).join('')}</tbody></table></div><p>${a.groups.length>30?'First 30 groups displayed. ':''}Differences in observed summaries do not by themselves establish an effect or statistical significance.</p>`:''}<details><summary>How to interpret these summaries</summary><p>The mean is the arithmetic average; the median is the middle ordered value and can differ when data are skewed or have outliers. Sample standard deviation uses n−1 and is undefined for a single observation. Check the measurement scale: numbers used as category labels are not automatically quantities.</p><p>Repeated records may not be independent. Missingness, recruitment and measurement affect interpretation. Record these limits before writing a conclusion.</p>${link('https://www.itl.nist.gov/div898/handbook/eda/eda.htm','NIST guidance on exploring data')}</details><div class="create-next"><button type="button" class="path-button" data-analysis-save>Save reproducible analysis to project</button><p data-analysis-save-status role="status"></p><button type="button" class="path-link" data-analysis-download>Download analysis report</button></div>`;}catch(e){return '<h2>Check the data first.</h2><p>'+esc(e.message)+'</p>';}}
 function render(parts){if(parts[0]==='create')return analysis();if(parts[1]==='model')return model();if(parts[1]==='study')return study(parts[2]);return papers();}
 function download(name,body,type='text/markdown;charset=utf-8'){const u=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),30000);}
 function analysisValues(form){const values=Object.fromEntries(new FormData(form));return {...values,run:false};}
 function updateAnalysisColumns(){const form=document.querySelector('[data-support-analysis]'),status=document.querySelector('[data-analysis-status]');if(!form)return;try{const v=analysisValues(form),d=C.dataset(v.csv);for(const key of ['x','y','group'])form.elements[key].innerHTML=options(d.headers,d.headers.includes(v[key])?v[key]:'',key==='x'?'Choose the measure':key==='y'?'No correlation':'No grouping');document.querySelector('[data-analysis-inspection]').textContent=d.rows.length+' rows · '+d.headers.length+' columns. Verify their meanings before calculating.';const s=store();s.analysis=analysisValues(form);save(s);document.querySelector('[data-analysis-output]').innerHTML='<h2>Columns inspected.</h2><p>Choose a numeric measure, then calculate the current data.</p>';status.textContent='Columns inspected. Choose a numeric measure and any optional comparison.';}catch(e){status.textContent=e.message;}}
 async function saving(button,status,operation){if(button.disabled)return;button.disabled=true;status.textContent='Saving…';try{await operation()}catch(e){status.textContent='Not completed. '+e.message+' Your current draft remains available.';}finally{if(button.isConnected)button.disabled=false;}}
 async function saveStudy(button){const s=D.studies.find(s=>s.id===button.dataset.studySave),status=document.querySelector('[data-study-save-status]');await saving(button,status,async()=>{const dest=window.REILibrary.destination(),r=await window.REIResearch.applyCreate({...dest,kind:'papers',records:[{...s,type:'journal-article'}]});window.REILibrary.rememberProject(r.id);const p=(await window.REIResearch.listSaved()).find(p=>p.id===r.id),source=p.papers.find(p=>p.doi.toLowerCase()===s.doi.toLowerCase());if(!source)throw Error('A title match exists with a different or missing DOI. Verify its metadata before attaching this PDF.');try{await window.REIWorkbench.attachStudyPDF(p,source.id,s.id);status.innerHTML='Source and original PDF are available. '+link('#research/'+p.id+'/reader','Open project Reader',true).replace('<a ','<a data-read-project="'+esc(p.id)+'" data-read-source="'+esc(source.id)+'" ');}catch(e){status.innerHTML='Source saved. PDF attachment was not completed: '+esc(e.message)+'. Retry this button; the saved source will not be duplicated. '+link('#research/'+p.id+'/reader','Open Reader');}});}
 function projectExtras(){const p=window.REIWorkbench?.getProject();if(!p||!location.hash.startsWith('#research/'))return;const room=location.hash.split('/')[2]||'library',content=document.querySelector('.research-content');if(!content)return;const n=C.nextStep(p);document.querySelector('.research-project-heading>p')?.insertAdjacentHTML('afterend',`<section class="support-next-step" aria-label="Suggested next step"><div><h2>${esc(n.label)}</h2><p>${esc(n.why)}</p></div><a class="text-link" href="${n.href}" data-support-destination="${p.id}">Continue this project</a></section>`);if(p.learningModel)content.insertAdjacentHTML('afterbegin','<p class="support-model-notice">Editable teaching example. Sources are real; the proposed local study has not been conducted.</p>');
 if(room==='synthesis'){content.insertAdjacentHTML('beforeend','<details class="wb-section support-concepts"><summary>See a small coding example</summary><p>Fictional teaching account: “I wait until after work to read course messages.” An initial code could be “scheduling communication around work.” Compare it with other accounts before proposing a theme; one excerpt alone does not establish a shared experience. Keep contrasting accounts and your interpretation visible.</p><p>Move through familiarization, initial coding, comparison, tentative themes and review. Explain the analytic approach and your role in interpretation. Counts of coded excerpts do not automatically estimate how common an experience is in the population.</p></details>');const rows=C.comparisons(p);content.insertAdjacentHTML('beforeend',`<section class="wb-section support-comparison"><h3>Compare what you have recorded</h3><p>Built directly from your saved notes. Blank cells identify missing records. REI does not infer agreement, contradictions or study quality.</p><div class="support-table-wrap" tabindex="0" aria-label="Scrollable data table"><table><caption>Source comparison from recorded evidence</caption><thead><tr>${['Source','Population / setting','Method','Findings / interpretation','Limitations','Locations'].map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${esc(r.source)}<small>${r.notes} notes</small></th>${['population','method','finding','limitation','locations'].map(k=>`<td>${esc(r[k]||'Not recorded')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${!rows.length?'<p>Add sources and evidence notes first.</p>':''}</section>`);}
 if(room==='design'){content.insertAdjacentHTML('beforeend',coachForm()+concepts()+analysisRecords(p));}
 if(room==='review'){content.insertAdjacentHTML('beforeend',handoffForm(p));}
 if(room==='reader'){const source=p.papers.find(s=>s.id===document.querySelector('#wb-reader-source')?.value),study=D.studies.find(s=>s.doi.toLowerCase()===source?.doi?.toLowerCase());if(study)document.querySelector('[data-wb-form=passage]')?.insertAdjacentHTML('beforeend',`<p>${link('#library/study/'+study.id,'Compare with the annotated teaching paper')}</p>`);document.querySelector('[data-wb-form=passage]')?.insertAdjacentHTML('beforeend','<p data-support-claim-feedback role="status"></p>');}
 if(room==='claims')document.querySelector('[data-wb-form=claim]')?.insertAdjacentHTML('beforeend','<p data-support-claim-feedback role="status"></p>');
 }
 function concepts(){return `<details class="wb-section support-concepts"><summary>Explain the method terms</summary><dl><dt>Construct and indicator</dt><dd>A construct is the idea, such as engagement. An indicator is what you record, such as responses to specified items. Logging in is not automatically the same as being engaged.</dd><dt>Sampling and scope</dt><dd>Selection determines whose evidence you have. A convenient set of volunteers does not automatically represent every student.</dd><dt>Confounding</dt><dd>Other differences can help explain an observed relationship. Students who choose an app may differ before using it.</dd><dt>Operational definition</dt><dd>Specify how an idea becomes an observation: for example, waiting time measured from joining a queue to service beginning, in minutes.</dd><dt>Analytic approach</dt><dd>Explain how the recorded evidence can answer the question. Computing a correlation and interpreting interview themes use different kinds of material and assumptions.</dd></dl></details>`;}
 const select=(name,label,choices)=>`<label>${label}<select name="${name}">${choices.map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></label>`;
 function coachForm(){return `<details class="wb-section support-coach"><summary>Check how your aim, evidence and analysis fit</summary><p>These explicit rules identify common mismatches. They do not establish design validity or replace subject expertise.</p><form data-support-coach class="research-form">${select('aim','Aim',[['experience','Understand experiences'],['describe','Describe a pattern'],['relationship','Study a relationship'],['effect','Estimate an effect']])}${select('evidence','Evidence you plan to collect',[['accounts','Text or participant accounts'],['numeric','Numeric measurements'],['both','Accounts and numeric measurements']])}${select('design','Design / comparison',[['interviews','Interviews or qualitative material'],['one-time','One-time observational collection'],['beforeafter','Before/after without a comparison'],['comparison','A justified non-random comparison'],['randomized','A justified randomized design']])}<label>Indicator, instrument or interview focus<input name="measure" maxlength="1000" required></label><label>Second construct, if studying a relationship<input name="second" maxlength="1000"></label>${select('analysis','Planned analysis',[['themes','Qualitative interpretation / themes'],['summary','Numeric descriptions'],['correlation','Numeric association'],['comparison','A justified outcome comparison']])}${select('sampling','Selection',[['convenience','Convenience / volunteers'],['purposeful','Purposeful qualitative selection'],['probability','A justified probability sample']])}${select('scope','Intended scope',[['local','Bounded to the sampled context'],['population','An estimate about the wider population']])}<button type="submit" class="button primary">Inspect alignment</button><div data-coach-result role="status"></div></form></details>`;}
 function analysisRecords(p){return `<section class="wb-section"><h3>Saved local analyses</h3><p>CSV inputs and settings are retained with each record for inspection and backup. These are descriptive analyses.</p>${(p.workbench.analyses||[]).map(a=>`<details><summary>${esc(a.values.source||'Analysis')} · ${esc(a.date.slice(0,10))}</summary><pre class="support-proposal">${esc(C.analysisText(a.values))}</pre></details>`).join('')||'<p>No analyses saved in this project.</p>'}${link('#create/analyze','Explore a CSV',true).replace('<a ','<a data-support-destination="'+esc(p.id)+'" ')}</section>`;}
 function handoffForm(p){return `<details class="wb-section support-handoff"><summary>Send a portable project handoff</summary><p>Download one complete project with its saved PDFs and a next-step note. Transfer the file yourself. The recipient imports a separate copy; edits do not synchronize or merge automatically.</p><form data-support-handoff class="research-form"><label>Sender or version label (optional)<input name="fromLabel" maxlength="180" placeholder="Example: Group A, review 2"></label><label>What should the next person do?<textarea name="nextAction" maxlength="2000" rows="3" required>${esc(C.nextStep(p).label)}</textarea></label><button class="button primary">Download complete project handoff</button><p data-handoff-status role="status"></p></form><ol><li>Open REI on the receiving device.</li><li>Open My projects, choose the backup and inspect the preview.</li><li>Import as a separate project and check the PDFs and next-step note.</li><li>Agree which copy is current before continuing. Keep older copies until the handoff is checked.</li></ol>${p.handoff?`<h3>Incoming handoff</h3><p>${esc(p.handoff.fromLabel||'Sender not labeled')} · ${esc(p.handoff.createdAt)}</p><p>${esc(p.handoff.nextAction)}</p>`:''}</details>`;}
 document.addEventListener('input',e=>{if(e.target.matches('[data-study-filter]')){const q=e.target.value.toLowerCase();let count=0;document.querySelectorAll('[data-study-item]').forEach(el=>{el.hidden=!el.dataset.studySearch.includes(q);if(!el.hidden)count++});document.querySelector('[data-study-count]').textContent=count+' matching studies';document.querySelector('[data-study-empty]').hidden=count>0;}if(e.target.matches('[data-study-reason]')){const s=store(),id=e.target.dataset.studyReason;s.papers[id]??={choice:null,reason:'',revealed:false};s.papers[id].reason=e.target.value;save(s);const paper=D.studies.find(s=>s.id===id);document.querySelector('[data-study-writing-feedback]').textContent=C.claimReview(e.target.value,paper.design).join(' ');}const form=e.target.closest('[data-support-analysis]');if(form){const s=store();s.analysis=analysisValues(form);save(s);document.querySelector('[data-analysis-output]').innerHTML='<h2>Inputs changed.</h2><p>Inspect columns if the CSV changed, then calculate again.</p>';}if(e.target.closest('[data-support-coach]')){const out=document.querySelector('[data-coach-result]');if(out)out.innerHTML='<p>Inputs changed. Inspect alignment again before saving a review note.</p>';}if(e.target.name==='findings'||e.target.name==='text'){const f=e.target.closest('[data-wb-form]'),out=f?.querySelector('[data-support-claim-feedback]');if(out)out.textContent=C.claimReview(e.target.value).join(' ');}});
 document.addEventListener('change',async e=>{if(e.target.matches('[data-study-choice]')){const s=store(),id=e.target.dataset.studyChoice;s.papers[id]??={choice:null,reason:'',revealed:false};s.papers[id].choice=Number(e.target.value);save(s);document.querySelector('[data-study-choice-feedback]').textContent=choiceFeedback(D.studies.find(s=>s.id===id),Number(e.target.value));}if(e.target.closest('[data-support-coach]')){const out=document.querySelector('[data-coach-result]');if(out)out.innerHTML='<p>Inputs changed. Inspect alignment again before saving a review note.</p>';}const form=e.target.closest('[data-support-analysis]');if(form&&!e.target.matches('[data-analysis-file]')){const s=store();s.analysis=analysisValues(form);save(s);document.querySelector('[data-analysis-output]').innerHTML='<h2>Inputs changed.</h2><p>Calculate again to inspect the current settings.</p>';}if(e.target.matches('[data-analysis-file]')){const file=e.target.files?.[0],status=document.querySelector('[data-analysis-status]');if(!file)return;try{if(file.size>100000)throw Error('Choose a CSV under 100 KB.');form.elements.csv.value=await file.text();form.elements.source.value=file.name;updateAnalysisColumns();}catch(error){status.textContent=error.message;}}});
 document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.matches('[data-study-save]'))return saveStudy(b);if(b.matches('[data-model-copy]'))return saving(b,document.querySelector('[data-model-status]'),async()=>{const p=await window.REIResearch.applyCreate({kind:'model'});window.REILibrary.rememberProject(p.id);const record=(await window.REIResearch.listSaved()).find(x=>x.id===p.id);let missing=0;for(const id of ['social','remote','engagement']){const study=D.studies.find(s=>s.id===id),source=record.papers.find(s=>s.doi.toLowerCase()===study.doi.toLowerCase());try{await window.REIWorkbench.attachStudyPDF(record,source.id,id)}catch{missing++;}}document.querySelector('[data-model-status]').innerHTML=(missing?missing+' original PDFs could not be attached. Retry this button to finish. ':'')+(p.added?'Practice project saved. ':'Your existing practice copy is available. ')+link('#research/'+p.id+'/library','Open practice project',true);});if(b.matches('[data-study-reveal]')){const s=store(),id=b.dataset.studyReveal;s.papers[id]??={choice:null,reason:'',revealed:false};s.papers[id].revealed=true;save(s);document.querySelector('[data-study-model]').hidden=false;}if(b.matches('[data-analysis-inspect]'))updateAnalysisColumns();if(b.matches('[data-analysis-example]')){const f=document.querySelector('[data-support-analysis]');f.elements.csv.value=C.sample;f.elements.source.value='Fictional practice data — not a published dataset';updateAnalysisColumns();}if(b.matches('[data-analysis-save]'))return saving(b,document.querySelector('[data-analysis-save-status]'),async()=>{const p=await window.REIResearch.applyCreate({...window.REILibrary.destination(),kind:'analysis',values:store().analysis});window.REILibrary.rememberProject(p.id);document.querySelector('[data-analysis-save-status]').innerHTML=(p.added?'Analysis and CSV saved. ':'The same analysis is already saved. ')+link('#research/'+p.id+'/design','Inspect saved analysis');});if(b.matches('[data-coach-save]'))return saving(b,document.querySelector('[data-coach-save-status]'),async()=>{const p=window.REIWorkbench.getProject(),values=C.reviewValues(Object.fromEntries(new FormData(b.closest('form')))),r=await window.REIResearch.applyCreate({kind:'method-review',projectId:p.id,values});document.querySelector('[data-coach-save-status]').textContent=r.added?'Review note saved in project decisions. Your existing methods were preserved.':'This review note is already recorded.';});if(b.matches('[data-analysis-download]'))download('rei-descriptive-analysis.md',C.analysisText(store().analysis));});
 document.addEventListener('click',e=>{const a=e.target.closest('[data-support-destination]');if(a){const s=window.REILearningStore.readLibrary();s.projectId=a.dataset.supportDestination;window.REILearningStore.writeLibrary(s);}});
 document.addEventListener('submit',async e=>{const f=e.target;if(f.matches('[data-support-analysis]')){e.preventDefault();const status=document.querySelector('[data-analysis-status]');try{const v=analysisValues(f);C.analyze(v);v.run=true;const s=store();s.analysis=v;save(s);const out=document.querySelector('[data-analysis-output]');out.innerHTML=analysisResult(v);out.focus({preventScroll:true});out.scrollIntoView({block:'start',behavior:'auto'});status.textContent='Calculated locally. Review exclusions and interpretation boundaries.';}catch(error){status.textContent=error.message;}return;}if(f.matches('[data-support-coach]')){e.preventDefault();const v=C.reviewValues(Object.fromEntries(new FormData(f))),issues=C.methodReview(v),out=f.querySelector('[data-coach-result]');out.innerHTML=issues.length?'<ul>'+issues.map(i=>`<li><strong>${esc(i.title)}</strong><p>${esc(i.detail)}</p></li>`).join('')+'</ul>':'<p>No predefined mismatch was detected. Review the measures, comparison, selection and analysis with a supervisor; this is not a validity judgment.</p>';out.insertAdjacentHTML('beforeend','<button type="button" class="button secondary" data-coach-save>Save this review note</button><p data-coach-save-status role="status"></p>');return;}if(f.matches('[data-support-handoff]')){e.preventDefault();const p=window.REIWorkbench.getProject(),values=Object.fromEntries(new FormData(f)),b=f.querySelector('button'),status=f.querySelector('[data-handoff-status]');await saving(b,status,async()=>{const raw=await window.REIWorkbench.backup(p,true,true);raw.project.handoff={version:1,originId:p.handoff?.originId||p.id,revisionId:crypto.randomUUID(),createdAt:new Date().toISOString(),fromLabel:values.fromLabel,nextAction:values.nextAction,baseUpdated:p.updated||''};C.validateProject(raw.project);download('rei-project-handoff.json',JSON.stringify(raw,null,2),'application/json');status.textContent='Handoff download requested. Check the file, transfer it yourself, and ask the recipient to validate the import and PDFs.';});}});
 addEventListener('rei:research-render',projectExtras);
 window.REISupport={render,nav};
})();
